def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y):
    return x * y // gcd(x, y)

def nthUglyNumber(n, a, b, c):
    def count(x):
        ab = lcm(a, b)
        ac = lcm(a, c)
        bc = lcm(b, c)
        abc = lcm(ab, c)
        # Inclusion-Exclusion
        return (
            x // a + x // b + x // c
            - x // ab - x // ac - x // bc
            + x // abc
        )
    left, right = 1, 2 * 10**9
    while left < right:
        mid = (left + right) // 2
        if count(mid) < n:
            left = mid + 1
        else:
            right = mid
    return left
